q.onCamp = @(__original) function()
{
	local before = ::World.getSpeedMult();
	local ret = __original();
	if (::World.Assets.isCamping())
	{
		// 扎营不改变时间流速：沿用扎营前的速度（暂停中扎营则为 ×1）
		if (before > 0)
		{
			this.m.LastWorldSpeedMult = before;
			::World.setSpeedMult(before);
		}
		::Quicker.updateTopbarButtons();
	}
	return ret;
}
